-- Seed: GST state / UT codes and unit quantity codes (Phase 3). Safe to run more than once (ON CONFLICT DO UPDATE).
-- Status: 'secondary_verified' = at least two independent secondary sources agree; NOT read from gst.gov.in (not reachable).
-- Codes 25 (Daman & Diu), 26 and 28 (undivided Andhra Pradesh) need CA / portal confirmation: kept 'pending'.
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, effective_from = EXCLUDED.effective_from,
    effective_to = EXCLUDED.effective_to, source_reference = EXCLUDED.source_reference,
    verification_status = EXCLUDED.verification_status, notes = EXCLUDED.notes;

-- UQC list recalled from the GSTR-1 HSN-summary list; NOT read from an official source: all 'pending'.
ON CONFLICT (code) DO UPDATE SET description = EXCLUDED.description, effective_from = EXCLUDED.effective_from,
    effective_to = EXCLUDED.effective_to, source_reference = EXCLUDED.source_reference, verification_status = EXCLUDED.verification_status;
